/* Rich synthetic object memories, scoped to the object in the selected Home.
   Purchase/warranty examples are not inferred from the user's documents.
   Gift copies never inherit these private cost, contact or service records. */
const OBJECT_EXAMPLES=[
 ['dish',650,'2025-03-12','2025-03-18','Lavastoviglie Serie Demo','DEMO-LV-001','14 coperti · classe energetica di esempio','Pulizia filtri e controllo tenuta',85,'2026-09-18','2027-03-18','2028-03-12'],
 ['boiler',2400,'2024-10-02','2024-10-08','Caldaia a condensazione Demo','DEMO-CL-002','24 kW · alimentazione a metano','Manutenzione caldaia',120,'2026-10-12','2026-11-05','2027-10-02'],
 ...systems.map(([name],i)=>['system-'+i,[1300,2800,2200,6500,3200,7800,4500,3100,1400,1700,450,1900,850,1200][i],'2025-04-10','2025-04-22',name+' · configurazione demo','DEMO-IMP-'+String(i+1).padStart(3,'0'),['Quadro a 12 moduli · schema di esempio','Distribuzione acqua calda e fredda','Due unità interne · dati di esempio','Tre zone · termostati indipendenti','Recupero di calore · filtri sostituibili','6 kWp · produzione solo illustrativa','5 kWh · capacità di esempio','Accumulo 200 litri · dati di esempio','Resina a scambio ionico · esempio','Centrale e sensori · configurazione di esempio','Unità interna e posto esterno · esempio','Tre zone luci · configurazione di esempio','Due zone irrigazione · esempio','7,4 kW · potenza di esempio'][i],['Controllo connessioni','Verifica perdite e filtri','Pulizia filtri e verifica scarico','Controllo collettori e regolazione','Sostituzione filtri','Controllo visivo e pulizia moduli','Verifica sistema di accumulo','Verifica circuito e accumulo','Pulizia e controllo resine','Prova sensori e batteria','Verifica audio e video','Controllo comandi e configurazione','Pulizia ugelli e prova zone','Verifica funzionale stazione'][i],[90,110,95,140,75,160,110,130,65,80,45,95,60,90][i],'2026-09-15','2027-04-22','2028-04-10'])
];
for(const [id,cost,purchased,installed,model,serial,spec,service,amount,date,next,end] of OBJECT_EXAMPLES){const o=P.homes.roma.objects.find(x=>x.id===id);if(!o)continue;o.cost=cost;o.model=model;o.warranty='Garanzia commerciale di esempio · fino al '+vDate(end);o.memory={purchased,installed,serial,spec,supplier:id==='dish'?'Rivenditore Demo':'Installatore Demo',warrantyEnd:end,warrantyTerms:'Copertura commerciale dimostrativa per difetti del prodotto. Consumabili, usura e danni accidentali esclusi in questo esempio. Condizioni da leggere nel facsimile.',serviceContact:id==='dish'?'Assistenza Elettrodomestici Demo':'Tecnico Impianti Demo',contactEmail:id==='dish'?'assistenza@example.test':'impianti@example.test',service:{title:service,amount,date,expense:id==='boiler'?'cost1':null,note:'Controllo eseguito e funzionamento verificato nella simulazione. Nessuna attestazione tecnica reale.'},next,nextNote:'Promemoria dimostrativo scelto per la casa; non è una scadenza normativa.',notes:id==='dish'?'Conserva il manuale e indica il programma usato quando chiedi assistenza.':'Conserva schema, manuale e riferimenti degli interventi. Valori esclusivamente dimostrativi.'};}
// Service examples also appear in the house's expense register, once each.
for(const o of P.homes.roma.objects){const m=o.memory;if(!m||m.service.expense)continue;const id='service-'+o.id;m.service.expense=id;P.homes.roma.expenses.push({id,name:m.service.title,amount:m.service.amount,date:m.service.date,supplier:m.serviceContact,object:o.id,doc:'',paid:false,work:''});}
function objectServiceRows(o){const entries=V5.expenses.filter(e=>e.object===o.id).map(e=>({title:e.name,amount:e.amount,date:e.date,expense:e.id,note:e.paid?'Pagamento dichiarato nella demo':'Pagamento da verificare'}));if(o.memory?.service&&!entries.some(e=>e.expense===o.memory.service.expense&&e.expense))entries.push(o.memory.service);return entries.sort((a,b)=>b.date.localeCompare(a.date));}
const memoryBaseObject=vObject;
vObject=function(id){const o=V5.objects.find(x=>x.id===id);if(!o)return;const m=o.memory,services=objectServiceRows(o),registered=V5.expenses.filter(e=>e.object===id).reduce((sum,e)=>sum+e.amount,0),docs=[...new Set([o.doc,...(o.documents||[])].filter(Boolean))];
 const value=(label,text)=>`<div><small>${esc(label)}</small><strong>${esc(text||'Da completare')}</strong></div>`;
 const source=(label,key)=>pButton(label,'object-source:'+id+':'+key,true);
 const tasks=V5.tasks.filter(t=>t.object===id),knownCost=m?money(o.cost):'Da verificare';
 vModal(o.name,`<p class="memory-origin">Memoria dell’oggetto · ${esc(o.room||'Senza ambiente')} · Solo nella casa selezionata</p><div class="memory-summary">${value('Acquisto · esempio',knownCost)}${value('Garanzia',o.warranty)}${value('Ultimo intervento',services.length?vDate(services[0].date):'Nessun intervento registrato')}${value('Prossimo promemoria',tasks.find(t=>!t.done)?.date?vDate(tasks.find(t=>!t.done).date):m?vDate(m.next)+' · suggerito':'Da scegliere')}</div>
 <details class="memory-section" open><summary>Acquisto e costi</summary><div class="memory-grid">${value('Prezzo d’acquisto',knownCost)}${value('Data acquisto',m?vDate(m.purchased):'Da verificare')}${value('Fornitore',m?.supplier)}${value('Installazione',m?vDate(m.installed):'Da verificare')}</div><p>Spese collegate nell’archivio: <strong>${money(registered)}</strong>. Il prezzo d’acquisto è distinto dalle spese di manutenzione.</p>${m?source('Fattura d’acquisto · facsimile','purchase'):''}${vButton('Vedi spese registrate','object-expenses:'+id,true)}</details>
 <details class="memory-section" open><summary>Garanzia e assistenza</summary><p><strong>${esc(o.warranty)}</strong></p><p>${m?esc(m.warrantyTerms):'Durata e coperture da verificare sui documenti. La Gift non trasferisce automaticamente una garanzia.'}</p>${m?source('Condizioni di garanzia · facsimile','warranty'):''}${vButton('Aggiorna garanzia','warranty:'+id,true)}</details>
 <details class="memory-section" open><summary>Manutenzioni e prossime attività</summary>${services.map(e=>`<article class="memory-service"><strong>${esc(e.title)}</strong><span>${vDate(e.date)} · ${money(e.amount)}</span><p>${esc(e.note)}</p>${e.expense?vButton('Apri spesa e fonte','expense:'+e.expense,true):source('Rapporto intervento · facsimile','service')}</article>`).join('')||'<p>Nessuna manutenzione ancora registrata per questo oggetto.</p>'}${tasks.map(t=>vRow(t.name,vDate(t.date)+' · '+(t.done?'Completata':'In programma'),'task:'+t.id,'Apri','◷')).join('')}${m?'<div class="memory-reminder"><strong>Prossimo controllo suggerito: '+vDate(m.next)+'</strong><p>'+esc(m.nextNote)+'</p></div>':''}${vButton('Aggiungi un promemoria','task-new:'+id,true)}</details>
 <details class="memory-section"><summary>Identità, dati tecnici e note</summary><div class="memory-grid">${value('Marca',o.brand)}${value('Modello',o.model)}${value('Matricola di esempio',m?.serial)}${value('Ambiente',o.room)}${value('Tipo',o.type)}${value('Caratteristiche',m?.spec)}</div><p>${esc(m?.notes||'Aggiungi le informazioni che hai verificato per questa casa.')}</p>${vButton('Modifica nome e tipo','object-edit:'+id,true)}${vButton('Cambia ambiente','placement:'+id,true)}</details>
 <details class="memory-section"><summary>Documenti e fonti</summary>${docs.map(d=>vRow(V5.documents.find(x=>x.id===d)?.name||'Fonte collegata','Documento della casa','document:'+d,'Consulta')).join('')||'<p>Nessun documento ancora collegato.</p>'}${m?source('Fattura d’acquisto','purchase')+source('Certificato di garanzia','warranty')+source('Rapporto di manutenzione','service'):''}</details>
 <details class="memory-section"><summary>Contatti utili</summary>${m?'<strong>'+esc(m.serviceContact)+'</strong><p>'+esc(m.contactEmail)+'</p><p>Assistenza e manutenzione · contatto fittizio, nessun invio o chiamata.</p>':'<p>Nessun contatto personale trasferito con la Gift.</p>'}${vButton('Apri rubrica della casa','contacts',true)}</details>
 <p class="tiny">Dati e documenti dimostrativi. Costi, condizioni e date sono esempi espliciti, non deduzioni né certificazioni.</p>`,vButton(o.archived?'Ripristina oggetto':'Archivia oggetto','object-archive:'+id,true));};
const memoryBaseAction=pAction;
pAction=function(a,args){if(a!=='object-source')return memoryBaseAction(a,args);const o=V5.objects.find(x=>x.id===args[0]),m=o?.memory,key=args[1];if(!m)return;const title=key==='purchase'?'Fattura d’acquisto':key==='warranty'?'Certificato di garanzia':'Rapporto di manutenzione';const body=key==='purchase'?`<p>Fornitore: ${esc(m.supplier)}</p><p>Data: ${vDate(m.purchased)} · Prezzo: ${money(o.cost)}</p><p>Installazione: ${vDate(m.installed)}</p><p>Pagamento: da verificare. Il costo non implica pagamento.</p>`:key==='warranty'?`<p>${esc(o.warranty)}</p><p>${esc(m.warrantyTerms)}</p><p>Fonte: condizioni commerciali del prodotto di esempio. Nessuna copertura legale dedotta.</p>`:`<p>${esc(m.service.title)}</p><p>${vDate(m.service.date)} · ${money(m.service.amount)}</p><p>${esc(m.service.note)}</p><p>Operatore: ${esc(m.serviceContact)}</p>`;pModal(title+' · '+o.name,'<div class="v5-original"><div class="eyebrow">Facsimile · dati fittizi</div><h3>'+esc(o.name)+'</h3><p>Casa: '+esc(state.selected)+'</p>'+body+'</div><p class="tiny">Fonte di esempio della scheda. Nessun originale reale o dato di altri immobili.</p>',pButton('Torna alla scheda','easy-object:'+o.id));};
const memoryBaseForm=vForm;
vForm=function(kind,id=''){memoryBaseForm(kind,id);const o=V5.objects.find(x=>x.id===id);if(kind==='task'&&o?.memory){$('#v5-name').value='Controllo · '+o.name;$('#v5-date').value=o.memory.next;}};
